=<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emissão de documentos</title>
<style>:root { --cor: {{ $json.cor }}; } {{ $json.css }}
.doc { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-top: 1px solid #ebe9f2; }
.doc > div { flex: 1; min-width: 0; }
.doc strong { display: block; }
.doc span { color: #6b6880; font-size: .88rem; }
.selo { font-size: .75rem; font-weight: 600; padding: 2px 8px; border-radius: 99px; margin-left: 6px; }
.selo.ativo { background: #e6f4ea; color: #1d6b3f; } .selo.outro { background: #fdecea; color: #b3261e; }
.aviso { color: #b3261e; font-size: .85rem; }
@media (max-width: 560px) { .doc { flex-wrap: wrap; } .doc .btn, .doc .aviso { width: 100%; text-align: center; } }
</style>
</head>
<body>
<header class="topo"><div>{{ $json.logo_url ? '<img src="' + $json.logo_url + '" alt="">' : '' }}<b>Emissão de documentos</b><small>{{ $json.email }}</small></div></header>
<main>
{{ $json.erro ? '<div class="erro"><strong>Não foi possível gerar o PDF.</strong> ' + $json.erro + '</div>' : '' }}
{{ $json.criado ? '<div class="ok"><span><strong>Documento cadastrado:</strong> ' + $json.criado.nome + '</span><a class="btn" href="' + $json.criado.href + '">Baixar PDF</a></div>' : '' }}
<div class="card">
  <div class="barra"><h1>Documentos ({{ $json.docs.length }})</h1><a class="btn" href="?novo">+ Novo documento</a></div>
  <p class="muted">Os mais recentes primeiro. O PDF é gerado na hora, a partir da planilha.</p>
  {{ $json.docs.map(d => `<div class="doc"><div><strong>${d.nome}</strong><span>${[d.tipo, d.curso, d.data].filter(Boolean).join(' · ')}</span><span class="selo ${d.ativo ? 'ativo' : 'outro'}">${d.status}</span></div>${d.problema ? `<span class="aviso">${d.problema}</span>` : `<a class="btn" href="${d.href}">Baixar PDF</a>`}</div>`).join('') }}
</div>
</main>
</body>
</html>
